import { DATASET } from "./data";
import type {
  Layer,
  ResearchAnchorCentrality,
  ResearchAnchorDimension,
  ResearchAnchorProfile,
  ResearchConfidence,
  ResearchCoverageSummary,
  ResearchExpectedDirection,
  ResearchFalsePositiveAudit,
  ResearchItemFunction,
  ResearchNeighborDiscriminant,
  ResearchQuestionCandidate,
  ResearchQualitativeDirection,
  ResearchTheoryContext,
} from "./types";

type CandidateSeed = Readonly<{
  id: string;
  layer: Layer;
  facetId: string;
  exactWording: string;
  itemFunction: ResearchItemFunction;
  expectedDirection: ResearchExpectedDirection;
  scholarlyRationale: string;
  whyItemIsNeeded: string;
  domain?: string;
  theoryContext?: ResearchTheoryContext;
  sameAnswerDifferentReasonRisk?: string;
  potentialAmbiguity?: string;
  socialDesirabilityRisk?: string;
  jurisdictionOrCulturalRisk?: string;
  temporalStabilityRisk?: string;
  confidence?: ResearchConfidence;
}>;

type TargetBlock = Readonly<{
  targetId: string;
  targetJustification: string;
  sourceIds: readonly string[];
  neighborLabels: readonly string[];
  scholarlyRationale: string;
  items: readonly CandidateSeed[];
}>;

const targetLabelFor = (targetId: string): string =>
  DATASET.ideologyNodes.find((node) => node.id === targetId)?.label
  ?? DATASET.ideologyRegistry.find((entry) => entry.id === targetId)?.label
  ?? targetId;

const item = (
  id: string,
  layer: Layer,
  facetId: string,
  exactWording: string,
  itemFunction: ResearchItemFunction,
  expectedDirection: ResearchExpectedDirection,
  scholarlyRationale: string,
  whyItemIsNeeded: string,
  options: Readonly<Partial<Omit<CandidateSeed, "id" | "layer" | "facetId" | "exactWording" | "itemFunction" | "expectedDirection" | "scholarlyRationale" | "whyItemIsNeeded">>> = {},
): CandidateSeed => ({
  id,
  layer,
  facetId,
  exactWording,
  itemFunction,
  expectedDirection,
  scholarlyRationale,
  whyItemIsNeeded,
  ...options,
});

const candidateFromSeed = (targetBlock: TargetBlock, seed: CandidateSeed): ResearchQuestionCandidate => ({
  id: seed.id,
  targetId: targetBlock.targetId,
  targetLabel: targetLabelFor(targetBlock.targetId),
  layer: seed.layer,
  targetJustification: targetBlock.targetJustification,
  exactWording: seed.exactWording,
  domain: seed.domain ?? seed.layer + " / " + seed.facetId,
  constructId: seed.facetId,
  facetId: seed.facetId,
  axisId: "facet:" + seed.facetId,
  theoryContext: seed.theoryContext ?? "mixed",
  itemFunction: seed.itemFunction,
  expectedDirection: seed.expectedDirection,
  neighborsDifferentiated: targetBlock.neighborLabels,
  scholarlyRationale: targetBlock.scholarlyRationale + " " + seed.scholarlyRationale,
  sourceIds: targetBlock.sourceIds,
  whyItemIsNeeded: seed.whyItemIsNeeded,
  sameAnswerDifferentReasonRisk: seed.sameAnswerDifferentReasonRisk ?? "A neighboring tradition may reach the same surface answer for a different reason. Compare the mechanism, principle, or institutional logic.",
  potentialAmbiguity: seed.potentialAmbiguity ?? "The item may be endorsed from more than one rationale; compare it with the named neighbors before promotion.",
  socialDesirabilityRisk: seed.socialDesirabilityRisk ?? "Use neutral wording and make disagreement socially acceptable; do not infer a personal identity from agreement.",
  jurisdictionOrCulturalRisk: seed.jurisdictionOrCulturalRisk ?? "Meaning may change across political systems, religious contexts, diasporas, or historical periods; cross-context review is pending.",
  temporalStabilityRisk: seed.temporalStabilityRisk ?? "Prefer a durable principle over a current party, politician, controversy, or policy event.",
  recommendedResponseFormat: "five-point-directional",
  confidence: seed.confidence ?? "moderate",
  reviewStatus: "research_candidate",
  promotionReview: {
    neighborDistinctness: "pending",
    neighborDistinctnessEvidence: "",
    crossCulturalJurisdictional: "pending",
    crossCulturalJurisdictionalEvidence: "",
    empiricalValidation: "not-run",
    empiricalValidationEvidence: "",
  },
});

const block = (
  targetId: string,
  targetJustification: string,
  sourceIds: readonly string[],
  neighborLabels: readonly string[],
  scholarlyRationale: string,
  items: readonly CandidateSeed[],
): TargetBlock => ({ targetId, targetJustification, sourceIds, neighborLabels, scholarlyRationale, items });

