type CompactSeed = readonly [
  Layer,
  string,
  string,
  ResearchItemFunction,
  ResearchExpectedDirection,
  string,
  string,
];

const compactBlock = (
  targetId: string,
  targetJustification: string,
  sourceIds: readonly string[],
  neighborLabels: readonly string[],
  scholarlyRationale: string,
  items: readonly CompactSeed[],
): TargetBlock =>
  block(
    targetId,
    targetJustification,
    sourceIds,
    neighborLabels,
    scholarlyRationale,
    items.map((seed, index, allItems) => {
      const [layer, facetId, exactWording, itemFunction, expectedDirection, itemRationale, whyItemIsNeeded] = seed;
      const ordinal = allItems.slice(0, index + 1).filter((itemSeed) => itemSeed[0] === layer).length;
      return item(
        `rc-${targetId}-${layer.slice(0, 1)}-${String(ordinal).padStart(2, "0")}`,
        layer,
        facetId,
        exactWording,
        itemFunction,
        expectedDirection,
        itemRationale,
        whyItemIsNeeded,
      );
    }),
  );

